begin;
create extension if not exists pgcrypto;
create table if not exists public.angelcare_marketplace_corporate_profiles(organization_id uuid primary key references public.angelcare_marketplace_b2b_organizations(id) on delete cascade,workforce_size int,site_count int,employee_parent_population int,current_benefits jsonb not null default '[]',absenteeism_concerns text,privacy_constraints jsonb not null default '{}',hr_approval_process jsonb not null default '{}',procurement_process jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_corporate_benefit_programs(program_id uuid primary key references public.angelcare_marketplace_b2b_programs(id) on delete cascade,eligibility_policy_id uuid,employer_contribution numeric(8,3),employee_contribution numeric(8,3),budget_amount numeric(16,2),currency_label text not null default 'Dh',enrollment_starts_at timestamptz,enrollment_ends_at timestamptz,renewal_mode text not null default 'manual' check(renewal_mode in('manual','automatic','contractual')),impact_reporting_frequency text not null default 'quarterly',check(coalesce(employer_contribution,0)>=0),check(coalesce(employee_contribution,0)>=0));
create table if not exists public.angelcare_marketplace_corporate_eligibility_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id) on delete cascade,program_id uuid not null references public.angelcare_marketplace_b2b_programs(id) on delete cascade,rule_key text not null,rule_type text not null check(rule_type in('employment_status','tenure','site','grade','dependent_age','family_status','custom')),configuration jsonb not null default '{}',status text not null default 'draft' check(status in('draft','review','approved','active','paused','archived')),priority int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(program_id,rule_key));
create table if not exists public.angelcare_marketplace_corporate_employee_eligibility(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id) on delete cascade,program_id uuid not null references public.angelcare_marketplace_b2b_programs(id) on delete cascade,beneficiary_reference text not null,eligibility_status text not null default 'pending' check(eligibility_status in('pending','eligible','ineligible','exception','suspended','expired')),evidence jsonb not null default '{}',effective_from date,effective_until date,reviewed_by uuid,reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(program_id,beneficiary_reference));
create table if not exists public.angelcare_marketplace_corporate_quota_allocations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id) on delete cascade,program_id uuid not null references public.angelcare_marketplace_b2b_programs(id) on delete cascade,beneficiary_reference text not null,period_key text not null,allocated_quantity numeric(12,2) not null default 0,consumed_quantity numeric(12,2) not null default 0,reserved_quantity numeric(12,2) not null default 0,remaining_quantity numeric(12,2) generated always as (greatest(allocated_quantity-consumed_quantity-reserved_quantity,0)) stored,status text not null default 'active' check(status in('active','exhausted','exception','suspended','expired')),updated_at timestamptz not null default now(),unique(program_id,beneficiary_reference,period_key),check(allocated_quantity>=0 and consumed_quantity>=0 and reserved_quantity>=0));
create table if not exists public.angelcare_marketplace_corporate_usage_records(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id),program_id uuid not null references public.angelcare_marketplace_b2b_programs(id),quota_id uuid not null references public.angelcare_marketplace_corporate_quota_allocations(id),beneficiary_reference text not null,service_reference text not null,quantity numeric(12,2) not null check(quantity>0),status text not null default 'consumed' check(status in('reserved','consumed','cancelled','reversed')),occurred_at timestamptz not null default now(),actor_id uuid,evidence jsonb not null default '{}');
create table if not exists public.angelcare_marketplace_corporate_impact_snapshots(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id),program_id uuid not null references public.angelcare_marketplace_b2b_programs(id),period_key text not null,eligible_population int,active_beneficiaries int,usage_count int,usage_rate numeric(8,3),satisfaction_score numeric(8,3),employee_contribution_total numeric(16,2),employer_contribution_total numeric(16,2),estimated_absence_hours_avoided numeric(16,2),metrics jsonb not null default '{}',status text not null default 'draft' check(status in('draft','review','approved','published','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(program_id,period_key));
create or replace function public.angelcare_marketplace_record_corporate_usage(p_quota_id uuid,p_quantity numeric,p_service_reference text,p_actor_id uuid) returns public.angelcare_marketplace_corporate_quota_allocations language plpgsql security definer set search_path=public as $$declare q public.angelcare_marketplace_corporate_quota_allocations;begin if p_quantity<=0 then raise exception 'Quantity must be positive';end if;select * into q from public.angelcare_marketplace_corporate_quota_allocations where id=p_quota_id for update;if q.id is null then raise exception 'Quota not found';end if;if q.status not in('active','exception') then raise exception 'Quota is not active';end if;if q.remaining_quantity<p_quantity then raise exception 'Insufficient quota';end if;insert into public.angelcare_marketplace_corporate_usage_records(organization_id,program_id,quota_id,beneficiary_reference,service_reference,quantity,status,actor_id) values(q.organization_id,q.program_id,q.id,q.beneficiary_reference,p_service_reference,p_quantity,'consumed',p_actor_id);update public.angelcare_marketplace_corporate_quota_allocations set consumed_quantity=consumed_quantity+p_quantity,status=case when remaining_quantity-p_quantity<=0 then 'exhausted' else status end,updated_at=now() where id=q.id returning * into q;return q;end$$;
insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values('marketplace.b2b.corporates.view','Voir Corporate & RH','B2B Corporate',false),('marketplace.b2b.corporates.manage','Gérer programmes Corporate','B2B Corporate',true),('marketplace.b2b.corporates.eligibility_manage','Gérer éligibilité et quotas','B2B Corporate',true),('marketplace.b2b.corporates.impact_view','Voir impact RH','B2B Corporate',false) on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive') and p.permission_key like 'marketplace.b2b.corporates.%' on conflict do nothing;
update public.angelcare_marketplace_modules set status='enabled',enabled=true,health_status='healthy',route_prefix='/angelcare-marketplace/admin/verticals/corporates',required_permissions=array['marketplace.b2b.corporates.view']::text[],version=version+1,updated_at=now() where introduced_by_mega_zip=15;
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.b2b.corporates.enabled','Corporate & HR Family Benefits','Programmes, éligibilité, quotas, usage et impact RH.',true,'active','Ultra Delivery 3/5 · Original MZ15') on conflict(flag_key) do update set enabled=true,status='active',reason=excluded.reason,updated_at=now();
alter table public.angelcare_marketplace_corporate_profiles enable row level security;alter table public.angelcare_marketplace_corporate_benefit_programs enable row level security;alter table public.angelcare_marketplace_corporate_eligibility_rules enable row level security;alter table public.angelcare_marketplace_corporate_employee_eligibility enable row level security;alter table public.angelcare_marketplace_corporate_quota_allocations enable row level security;alter table public.angelcare_marketplace_corporate_usage_records enable row level security;alter table public.angelcare_marketplace_corporate_impact_snapshots enable row level security;
revoke all on table public.angelcare_marketplace_corporate_profiles,public.angelcare_marketplace_corporate_benefit_programs,public.angelcare_marketplace_corporate_eligibility_rules,public.angelcare_marketplace_corporate_employee_eligibility,public.angelcare_marketplace_corporate_quota_allocations,public.angelcare_marketplace_corporate_usage_records,public.angelcare_marketplace_corporate_impact_snapshots from anon,authenticated;grant all on table public.angelcare_marketplace_corporate_profiles,public.angelcare_marketplace_corporate_benefit_programs,public.angelcare_marketplace_corporate_eligibility_rules,public.angelcare_marketplace_corporate_employee_eligibility,public.angelcare_marketplace_corporate_quota_allocations,public.angelcare_marketplace_corporate_usage_records,public.angelcare_marketplace_corporate_impact_snapshots to service_role;grant execute on function public.angelcare_marketplace_record_corporate_usage(uuid,numeric,text,uuid) to service_role;
commit;
